-- key = "u_"..userId ; value = {lock={jobId,time}, data={...}}
function load(player)
  for i = 1, 5 do
    local ok, res = pcall(store.UpdateAsync, store, key(player), function(old)
      old = old or {data = default()}
      local l = old.lock
      if l and l.jobId ~= game.JobId and os.time() - l.time < 90 then return nil end -- locked elsewhere
      old.lock = {jobId = game.JobId, time = os.time()}
      return old
    end)
    if ok and res and res.lock.jobId == game.JobId then return res.data end
    task.wait(2 * i) -- wait for the old server to release
  end
  player:Kick("Data busy, rejoin")
end
function save(player, release)
  store:UpdateAsync(key(player), function(old)
    if not old or not old.lock or old.lock.jobId ~= game.JobId then return nil end -- lost lock: don't overwrite
    old.data = profiles[player]
    old.lock = release and nil or {jobId = game.JobId, time = os.time()}
    return old
  end)
end
```
Autosave about every 60-120 s (this refreshes the lock). Save with release on PlayerRemoving and in BindToClose. Before teleporting, save and release, and only then call TeleportAsync. Trades and item grants only change the session-locked profile. Purchases are recorded per PurchaseId.
